table(Tex.whiteui, t -> {
    t.color.set(color);
    t.addListener(new HandCursorListener());
    t.margin(6f);
    t.touchable = Touchable.enabled;
    t.add(st.localizedName()).style(Styles.outlineLabel).name("statement-name").color(color).padRight(8);
    t.add().growX();
    addressLabel = t.add(index + "").style(Styles.outlineLabel).color(color).padRight(8).get();
    //taken from foo's client
    t.button(Icon.add, Styles.logici, () -> Vars.ui.logic.showAddDialog(index + 1)).disabled(b -> canvas.statements.getChildren().size >= LExecutor.maxInstructions).size(24f).padRight(6);
    t.button(Icon.copy, Styles.logici, () -> {
    }).size(24f).padRight(6).disabled(i -> canvas.statements.getChildren().size >= LExecutor.maxInstructions).get().tapped(this::copy);
    t.button(Icon.cancel, Styles.logici, () -> {
        remove();
        dragging = null;
        statements.updateJumpHeights = true;
    }).size(24f);
    t.addListener(new InputListener() {

        float lastx, lasty;

        @Override
        public boolean touchDown(InputEvent event, float x, float y, int pointer, KeyCode button) {
            //don't start dragging when pressing the menu buttons
            if (event.targetActor instanceof Image)
                return false;
            if (button == KeyCode.mouseMiddle) {
                copy();
                return false;
            }
            Vec2 v = localToParentCoordinates(Tmp.v1.set(x, y));
            lastx = v.x;
            lasty = v.y;
            dragging = StatementElem.this;
            toFront();
            statements.updateJumpHeights = true;
            statements.invalidate();
            return true;
        }

        @Override
        public void touchDragged(InputEvent event, float x, float y, int pointer) {
            Vec2 v = localToParentCoordinates(Tmp.v1.set(x, y));
            translation.add(v.x - lastx, v.y - lasty);
            lastx = v.x;
            lasty = v.y;
            statements.invalidate();
        }

        @Override
        public void touchUp(InputEvent event, float x, float y, int pointer, KeyCode button) {
            statements.finishLayout();
        }
    });
}).growX().height

